1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  markInvoicePaid,
7	  voidInvoice,
8	  generateInvoiceForServer,
9	  regenerateMissingInvoices,
10	} from "@/lib/actions-billing";
11	
12	export function InvoiceAdminActions({ id, status }: { id: string; status: string }) {
13	  const router = useRouter();
14	  const [pending, start] = useTransition();
15	  const [err, setErr] = useState<string | null>(null);
16	
17	  const run = (fn: () => Promise<unknown>) => {
18	    setErr(null);
19	    start(async () => {
20	      try {
21	        await fn();
22	        router.refresh();
23	      } catch (e) {
24	        setErr(e instanceof Error ? e.message : "Action failed");
25	      }
26	    });
27	  };
28	
29	  const terminal = status === "VOID";
30	  return (
31	    <div className="flex flex-wrap items-center gap-2">
32	      <button
33	        className="btn-secondary py-1.5"
34	        disabled={pending || status === "PAID" || terminal}
35	        onClick={() => run(() => markInvoicePaid(id))}
36	      >
37	        Mark paid
38	      </button>
39	      <button
40	        className="btn-danger py-1.5"
41	        disabled={pending || status === "PAID" || terminal}
42	        onClick={() => {
43	          if (window.confirm("Void this invoice? It will no longer be collectible.")) {
44	            run(() => voidInvoice(id));
45	          }
46	        }}
47	      >
48	        Void
49	      </button>
50	      {err && <span className="text-xs text-red-400">{err}</span>}
51	    </div>
52	  );
53	}
54	
55	export function GenerateInvoiceButton({
56	  serverId,
57	  label = "Generate invoice",
58	}: {
59	  serverId: string;
60	  label?: string;
61	}) {
62	  const router = useRouter();
63	  const [pending, start] = useTransition();
64	  const [err, setErr] = useState<string | null>(null);
65	  return (
66	    <div className="flex items-center gap-2">
67	      <button
68	        className="btn-secondary py-1.5"
69	        disabled={pending}
70	        onClick={() => {
71	          setErr(null);
72	          start(async () => {
73	            try {
74	              await generateInvoiceForServer(serverId);
75	              router.refresh();
76	            } catch (e) {
77	              setErr(e instanceof Error ? e.message : "Failed");
78	            }
79	          });
80	        }}
81	      >
82	        {pending ? "Generating…" : label}
83	      </button>
84	      {err && <span className="text-xs text-red-400">{err}</span>}
85	    </div>
86	  );
87	}
88	
89	export function RegenerateMissingButton() {
90	  const router = useRouter();
91	  const [pending, start] = useTransition();
92	  const [msg, setMsg] = useState<string | null>(null);
93	  return (
94	    <div className="flex items-center gap-2">
95	      <button
96	        className="btn-secondary py-1.5"
97	        disabled={pending}
98	        onClick={() => {
99	          setMsg(null);
100	          start(async () => {
101	            try {
102	              const r = await regenerateMissingInvoices();
103	              setMsg(`${r.created} created`);
104	              router.refresh();
105	            } catch (e) {
106	              setMsg(e instanceof Error ? e.message : "Failed");
107	            }
108	          });
109	        }}
110	      >
111	        {pending ? "Backfilling…" : "Backfill missing"}
112	      </button>
113	      {msg && <span className="text-xs text-slate-400">{msg}</span>}
114	    </div>
115	  );
116	}
