39	          </div>
40	          <div className="flex flex-wrap gap-2">
41	            {state.codes.map((c) => (
42	              <span key={c} className="rounded bg-black/20 px-2 py-1 font-mono text-xs text-emerald-200">
43	                {c}
44	              </span>
45	            ))}
46	          </div>
47	        </div>
48	      )}
49	      <div>
50	        <label className="label">Amount (USD)</label>
51	        <input
52	          className="input"
53	          name="amount"
54	          type="number"
55	          min={0.01}
56	          step="0.01"
57	          placeholder="25.00"
58	          required
59	        />
60	      </div>
61	      <div>
62	        <label className="label">How many</label>
63	        <input className="input" name="count" type="number" min={1} max={100} defaultValue={1} />
64	        <p className="mt-1 text-[11px] text-slate-500">Bulk-generate up to 100</p>
