1	"use client";
2	
3	import { useActionState, useEffect, useRef, useState, useTransition } from "react";
4	import {
5	  adminSaveGamePlan,
6	  adminToggleGamePlan,
7	  adminDeleteGamePlan,
8	} from "@/lib/actions-gameplans";
9	
10	export type PlanOpt = { id: string; name: string; ramMB: number; diskGB: number };
11	export type ImageOpt = { id: string; name: string; family: string };
12	export type GamePlanRow = {
13	  id: string;
14	  gameFamily: string;
15	  name: string;
16	  ramMB: number;
17	  cpuCores: number;
18	  diskGB: number;
19	  slots: number | null;
20	  priceCents: number;
21	  termMonths: number;
22	  basePlanId: string;
23	  osTemplateId: string | null;
24	  featured: boolean;
25	  active: boolean;
26	  sortOrder: number;
27	};
28	
29	const GAME_FAMILIES = ["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"] as const;
30	
31	/**
32	 * Create/edit form for a single GamePlan tier. Used both inline on each existing
33	 * tier (collapsed behind an "Edit" toggle) and as the bottom "new tier" card.
34	 */
35	export function GamePlanForm({
36	  plan,
37	  plans,
38	  images,
39	  defaultGame,
40	  onSaved,
41	}: {
42	  plan?: GamePlanRow;
43	  plans: PlanOpt[];
44	  images: ImageOpt[];
45	  defaultGame?: string;
46	  onSaved?: () => void;
47	}) {
48	  const [state, action, pending] = useActionState(adminSaveGamePlan, {} as { error?: string; ok?: boolean });
49	  const formRef = useRef<HTMLFormElement>(null);
50	  const [game, setGame] = useState(plan?.gameFamily ?? defaultGame ?? GAME_FAMILIES[0]);
51	
52	  useEffect(() => {
53	    if (state?.ok) {
54	      if (!plan) formRef.current?.reset();
55	      onSaved?.();
56	    }
57	  }, [state, plan, onSaved]);
58	
59	  const gameImages = images.filter((i) => i.family === game);
60	
61	  return (
62	    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
63	      {plan && <input type="hidden" name="id" value={plan.id} />}
64	      {state?.error && (
65	        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
66	          {state.error}
67	        </div>
68	      )}
69	      {state?.ok && (
70	        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
71	          Saved.
72	        </div>
73	      )}
74	
75	      <div>
76	        <label className="label">Game</label>
77	        <select className="input" name="gameFamily" value={game} onChange={(e) => setGame(e.target.value)}>
78	          {GAME_FAMILIES.map((g) => (
79	            <option key={g} value={g}>
80	              {g}
81	            </option>
82	          ))}
83	        </select>
84	      </div>
