6	// ---------- Customer: request a payout ----------
7	
8	/**
9	 * Payout request form for the customer affiliate page. `availableCents` and
10	 * `minCents` come from the server (lib/affiliate); the amount defaults to the
11	 * full available balance. The server action re-validates the guard regardless of
12	 * what's posted here.
13	 */
14	export function PayoutRequestForm({
15	  availableCents,
16	  minCents,
17	  currency = "USD",
18	}: {
19	  availableCents: number;
20	  minCents: number;
21	  currency?: string;
22	}) {
23	  const [amount, setAmount] = useState<string>((availableCents / 100).toFixed(2));
24	  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
25	  const [pending, start] = useTransition();
26	
27	  const eligible = availableCents >= minCents;
28	
29	  const submit = (e: React.FormEvent) => {
30	    e.preventDefault();
31	    setMsg(null);
32	    const cents = Math.round(Number(amount) * 100);
33	    if (!Number.isFinite(cents) || cents <= 0) {
34	      setMsg({ error: "Enter a valid amount." });
35	      return;
36	    }
37	    start(async () => {
38	      const res = await requestAffiliatePayout(cents);
39	      setMsg(res);
40	    });
41	  };
42	
43	  if (!eligible) {
44	    return (
45	      <p className="text-sm text-slate-400">
46	        You need at least{" "}
47	        <span className="font-semibold text-slate-200">${(minCents / 100).toFixed(2)}</span>{" "}
48	        available to request a payout. Keep referring to reach the threshold.
49	      </p>
50	    );
51	  }
52	
53	  return (
54	    <form onSubmit={submit} className="space-y-3">
55	      {msg?.error && (
56	        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
57	          {msg.error}
58	        </div>
59	      )}
60	      {msg?.ok && (
61	        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
62	          Payout requested — we&apos;ll review and process it shortly.
63	        </div>
64	      )}
65	      <div className="flex flex-wrap items-end gap-2">
66	        <div>
67	          <label className="label">Amount ({currency})</label>
68	          <input
69	            className="input w-36"
70	            type="number"
71	            min={(minCents / 100).toFixed(2)}
72	            max={(availableCents / 100).toFixed(2)}
73	            step="0.01"
74	            value={amount}
75	            onChange={(e) => setAmount(e.target.value)}
76	          />
77	        </div>
78	        <button className="btn-primary" disabled={pending}>
79	          {pending ? "Requesting…" : "Request payout"}
80	        </button>
81	      </div>
82	      <p className="text-[11px] text-slate-500">
83	        Minimum ${(minCents / 100).toFixed(2)}. Available ${(availableCents / 100).toFixed(2)}.
84	        Payouts are reviewed and paid manually.
85	      </p>
86	    </form>
87	  );
88	}
