90	// ---------- Admin: payout status controls ----------
91	
92	const NEXT_ACTIONS: Record<string, { label: string; status: string; cls: string }[]> = {
93	  PENDING: [
94	    { label: "Approve", status: "APPROVED", cls: "btn-secondary" },
95	    { label: "Decline", status: "DECLINED", cls: "btn-danger" },
96	  ],
97	  APPROVED: [
98	    { label: "Mark paid", status: "PAID", cls: "btn-primary" },
99	    { label: "Decline", status: "DECLINED", cls: "btn-danger" },
100	  ],
101	  DECLINED: [{ label: "Reopen", status: "PENDING", cls: "btn-secondary" }],
102	  PAID: [],
103	};
104	
105	export function PayoutStatusControls({ id, status }: { id: string; status: string }) {
106	  const [pending, start] = useTransition();
107	  const [error, setError] = useState<string | null>(null);
108	  const actions = NEXT_ACTIONS[status] ?? [];
109	
110	  if (actions.length === 0) {
111	    return <span className="text-xs text-slate-500">—</span>;
112	  }
113	
114	  const run = (next: string, confirmMsg?: string) => {
115	    if (confirmMsg && !confirm(confirmMsg)) return;
116	    setError(null);
117	    start(async () => {
118	      const res = await adminUpdatePayout(id, next);
119	      if (res?.error) setError(res.error);
120	    });
121	  };
122	
123	  return (
124	    <div className="flex flex-col items-end gap-1">
125	      <div className="flex items-center justify-end gap-1">
126	        {actions.map((a) => (
127	          <button
128	            key={a.status}
129	            className={`${a.cls} py-1 text-xs`}
130	            disabled={pending}
131	            onClick={() =>
132	              run(
133	                a.status,
134	                a.status === "PAID"
135	                  ? "Mark this payout as PAID? This records it as cashed out."
136	                  : a.status === "DECLINED"
137	                    ? "Decline this payout request?"
138	                    : undefined
139	              )
140	            }
141	          >
