331	/**
332	 * Has real money actually reached Nxeon for this user?
333	 *
334	 * The evidence is a wallet credit carrying a Stripe identifier: `stripeSessionId`
335	 * (Checkout) or `stripePaymentIntentId` (an off-session renewal charge). Both are
336	 * written only by lib/stripe.ts / lib/stripe-cards.ts after Stripe confirmed a
337	 * payment, and both are UNIQUE, so neither can be forged or replayed by a caller.
338	 *
339	 * DELIBERATELY NOT accepted as proof, each for a reason:
340	 *
341	 *   - a positive `WalletTransaction` on its own. Signup credit, admin credit,
342	 *     gift credit and the referral bonus itself are all positive rows. Accepting
343	 *     them would let free credit bootstrap more free credit.
344	 *   - a negative (spend) row. Spending proves only that a balance existed, not
345	 *     that anyone paid for it — an account funded by signup credit could buy the
346	 *     cheapest product and claim the reward, which is the same attack one step
347	 *     further along.
348	 *   - the demo gateway in `topUp`. It mints balance with no payment; it is
349	 *     refused outright when NODE_ENV is production or Stripe is configured, so it
350	 *     only ever runs on a developer's machine. Exercising the referral path
351	 *     locally needs Stripe test mode — the alternative is a rule that says "in
352	 *     some builds, unpaid counts as paid", and that is how this bug happens
353	 *     again.
354	 *
355	 * Fails CLOSED: a user whose wallet was funded by someone else's payment (a gift)
356	 * does not qualify, and gets no reward. Refusing a legitimate $5 is recoverable
357	 * by hand; paying an illegitimate $10 per fake account is not.
358	 */
359	async function hasPaidAction(userId: string): Promise<boolean> {
360	  const paid = await db.walletTransaction.count({
361	    where: {
362	      userId,
363	      OR: [{ stripeSessionId: { not: null } }, { stripePaymentIntentId: { not: null } }],
364	    },
365	  });
366	  return paid > 0;
367	}
368	
369	/**
370	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
371	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
372	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
373	 * Callable from `topUp` in lib/actions.ts, from `placeOrder` in lib/order.ts and
374	 * from `creditCheckoutSession` in lib/stripe.ts — after a paid action.
375	 *
376	 * ── WHY "AFTER A PAID ACTION" IS CHECKED HERE, NOT TRUSTED ───────────────────
377	 *
378	 * This function is an exported member of a `"use server"` module, so it is a
379	 * network endpoint: a stranger can POST to it. `assertInternalGrowthCaller`
380	 * closes the "credit someone ELSE" hole, and its rule is "if there is a session,
381	 * it must be the account being credited".
382	 *
383	 * That rule does not close, and cannot close, the hole that matters most, because
384	 * the attacker's account IS the account being credited. Signed in as themselves,
385	 * they satisfy that guard by construction — it is the attacker's own case.
386	 *
387	 * The precondition that made this safe — "only call me after money changed
388	 * hands" — lived ENTIRELY in the three callers. A caller-held precondition is no
389	 * precondition at all for a function anyone can call directly. With
390	 * `referral_reward_cents` defaulting to 500 and paid to BOTH sides, each fake
391	 * signup that reached this endpoint minted ~$10 of spendable wallet balance at
392	 * zero spend, repeatable per account and limited only by how fast accounts can
393	 * be created.
394	 *
395	 * So the precondition is enforced here now, against the ledger, and no caller is
396	 * trusted to have checked it.
397	 */
398	export async function maybeRewardReferral(userId: string): Promise<boolean> {
399	  await assertInternalGrowthCaller(userId);
400	  // Feature flag: the referral program can be switched off platform-wide.
401	  if (!(await getSettingBool("feature_referrals", true))) return false;
402	
403	  // THE PRECONDITION. Checked before anything is read about the referral and
404	  // long before anything is written, so the endpoint is inert for an account
405	  // that has never paid — which is every account an attacker can create.
406	  if (!(await hasPaidAction(userId))) return false;
407	
408	  // Settings → Growth writes `referral_reward_cents` and displays it, but NOTHING
409	  // read it — the payout used the env-backed `referralRewardCents()` instead, so an
410	  // operator changing the reward saw "Saved." and the platform kept paying the old
411	  // amount. Same shape as the domain markup showing 0% while charging 25%, and the
412	  // auto-suspend switch that silenced nothing.
413	  //
414	  // Clamped, and the ceiling matters more here than anywhere else: this reward is
415	  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
416	  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
417	  // already absurd; anything beyond it is certainly a typo.
418	  const reward = Math.min(
419	    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
420	    100_000
421	  );
422	  if (reward <= 0) return false;
423	
424	  const user = await db.user.findUnique({ where: { id: userId } });
425	  if (!user || !user.referredById || user.referralRewardedAt) return false;
426	  const referrerId = user.referredById;
427	
428	  // Atomically claim the reward; if another concurrent action already did, bail.
429	  const claim = await db.user.updateMany({
430	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
431	    data: { referralRewardedAt: new Date() },
432	  });
433	  if (claim.count === 0) return false;
434	
435	  await db.$transaction([
436	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
437	    db.walletTransaction.create({
438	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
439	    }),
440	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
441	    db.walletTransaction.create({
442	      data: {
443	        userId: referrerId,
444	        amountCents: reward,
445	        description: "Referral bonus — you referred a friend",
446	      },
447	    }),
448	  ]);
449	
450	  // Best-effort in-app notifications, filtered through the notification policy.
451	  //
452	  // `referral_bonus` is ACCOUNT tier, so the in-app bell is never suppressed —
453	  // these rows are the customer's record of money that entered their wallet, and
454	  // hiding a credit would be the same "it silently disappeared" failure the
455	  // preferences exist to cure. The gate is here anyway so the tier in
456	  // `lib/prefs.ts` stays the single decider: if this kind is ever reclassified,
457	  // the filter starts biting without anyone having to remember this call site.
458	  try {
459	    const rows = [
460	      {
461	        userId,
462	        title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
463	        href: "/dashboard/billing",
464	      },
465	      {
466	        userId: referrerId,
467	        title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
468	        href: "/dashboard/refer",
469	      },
470	    ];
471	    const allowed: typeof rows = [];
472	    for (const row of rows) {
473	      if (await mayDeliverTo(row.userId, "referral_bonus", "inapp")) allowed.push(row);
474	    }
475	    if (allowed.length > 0) await db.notification.createMany({ data: allowed });
476	  } catch {
477	    /* best-effort */
478	  }
479	  return true;
480	}
