202	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
203	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
204	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
205	    return { error: "Unknown game family." };
206	  }
207	
208	  // Resolve the game image: the tier's own OsTemplate, else any active image for
209	  // this game family. A game server can't provision without an image.
210	  let osTemplateId = gp.osTemplateId;
211	  if (osTemplateId) {
212	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
213	    if (!os?.active) osTemplateId = null;
214	  }
215	  if (!osTemplateId) {
216	    const os = await db.osTemplate.findFirst({
217	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
218	      orderBy: { sortOrder: "asc" },
219	    });
220	    if (!os) return { error: "No game image is configured for this game yet." };
221	    osTemplateId = os.id;
222	  }
223	
224	  const chargeCents = gp.priceCents;
225	  if (user.balanceCents < chargeCents) {
226	    return { error: "Insufficient balance. Top up your wallet first." };
227	  }
228	
229	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
230	  // letting game servers commit host RAM past capacity. Check the base plan's
231	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
232	  const capacity = await capacityCheck(gp.basePlanId);
233	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
234	
235	  const hostname = `${gp.gameFamily}-${rand()}`;
236	
237	  let server;
238	  try {
239	    server = await db.$transaction(async (tx) => {
240	      await debitWallet(tx, user.id, chargeCents);
241	      await tx.walletTransaction.create({
242	        data: {
243	          userId: user.id,
244	          amountCents: -chargeCents,
245	          description: `Game server: ${gp.name} (${gp.gameFamily})`,
246	        },
247	      });
248	      const s = await tx.server.create({
249	        data: {
250	          name: hostname,
251	          hostname,
252	          userId: user.id,
253	          planId: gp.basePlanId,
254	          gamePlanId: gp.id,
255	          osTemplateId: osTemplateId!,
256	          termMonths: gp.termMonths,
257	          // A game plan is a flat all-in price: `chargeCents` above is
258	          // `gp.priceCents` with no term discount and no seasonal promo applied, and
259	          // renewalCharge (lib/stripe-cards.ts) renews it at that same flat price.
260	          // So this term was sold at 0% off — full price — and any proration must
261	          // price against that, not against whatever promo is running later.
262	          termPromoPercent: 0,
263	          wantsDedicatedIp: false,
264	          expiresAt: addMonths(new Date(), gp.termMonths),
265	        },
266	      });
267	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
268	      return s;
269	    });
270	  } catch (e) {
271	    if (e instanceof InsufficientBalanceError) {
272	      return { error: "Insufficient balance. Top up your wallet first." };
273	    }
274	    throw e;
275	  }
276	
277	  await db.auditLog.create({
278	    data: {
279	      userId: user.id,
280	      action: "gameserver.order",
281	      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
282	    },
283	  });
284	  redirect(`/dashboard/servers/${server.id}`);
285	}
