364	export async function getEmailDnsRecords(
365	  subscriptionId: string,
366	): Promise<{
367	  error?: string;
368	  records?: DnsRecord[];
369	  verified?: boolean;
370	  external?: boolean;
371	  cloudflareConnected?: boolean;
372	}> {
373	  const user = await requireUser();
374	
375	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
376	  if (!sub) return { error: "Subscription not found." };
377	  if (sub.userId !== user.id) return { error: "Not your subscription." };
378	
379	  const domain = sub.domainName;
380	
381	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
382	  let dkimTxt = sub.dkimRecord ?? null;
383	  if (!dkimTxt && mailcowConfigured()) {
384	    try {
385	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
386	      if (!(await mcDomainExists(domain))) {
387	        await mcCreateDomain(domain).catch(() => {});
388	      }
389	      dkimTxt = await mcGetDkim(domain);
390	      if (dkimTxt) {
391	        await db.emailSubscription
392	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
393	          .catch(() => {});
394	      }
395	    } catch (e) {
396	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
397	    }
398	  }
399	
400	  const records: DnsRecord[] = [
401	    {
402	      type: "TXT",
403	      label: "Ownership verification",
404	      host: `_nxeon-verify.${domain}`,
405	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
406	      note: "Proves you control this domain. Required before mail is enabled.",
407	    },
408	    {
409	      type: "MX",
410	      label: "Mail routing (MX)",
411	      host: domain,
412	      value: MAIL_HOST,
413	      priority: MAIL_MX_PRIORITY,
414	    },
415	    {
416	      type: "TXT",
417	      label: "SPF",
418	      host: domain,
419	      value: SPF_VALUE,
420	      note: "Authorizes the Nxeon mail server to send for your domain.",
421	    },
422	    {
423	      type: "TXT",
424	      label: "DKIM",
425	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
426	      value: dkimTxt ?? "",
427	      note: dkimTxt
428	        ? undefined
429	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
430	    },
431	    {
432	      type: "TXT",
433	      label: "DMARC",
434	      host: `_dmarc.${domain}`,
435	      value: DMARC_VALUE,
436	      note: "Reporting policy for messages that fail SPF/DKIM.",
437	    },
438	  ];
439	
440	  return {
441	    records,
442	    verified: sub.verified,
443	    external: sub.external,
444	    // True for either connection shape (OAuth credentials or a legacy token).
445	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
446	  };
