707	/** Remove a mailbox the caller owns (via its subscription). */
708	export async function removeMailbox(mailboxId: string): Promise<Result> {
709	  const user = await requireUser();
710	
711	  const mailbox = await db.mailbox.findUnique({
712	    where: { id: mailboxId },
713	    include: { subscription: true },
714	  });
715	  if (!mailbox) return { error: "Mailbox not found." };
716	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
717	
718	  // Delete on Mailcow BEFORE dropping our row — and distinguish the two failure
719	  // modes, because they demand opposite actions:
720	  //
721	  //   - Mailcow REFUSED (reachable, returned an error): the mail server and our
722	  //     database disagree about this mailbox. Deleting our row here would leave a
723	  //     LIVE mailbox still receiving the customer's mail with no record of it in
724	  //     the product — silent data loss. Surface the error and keep the row.
725	  //   - Mailcow UNREACHABLE (transport failure): the server may just be down.
726	  //     Blocking removal forever on an outage is wrong, so we drop our row and
727	  //     tell the customer the mailbox itself may still exist and to retry once
728	  //     mail service is back.
729	  //
730	  // The previous `.catch(() => {})` collapsed both into "deleted, ok:true" — the
731	  // worse answer in every case.
732	  let mailcowUnreachable = false;
733	  if (mailcowConfigured()) {
734	    try {
735	      await mcDeleteMailbox(mailbox.address);
736	    } catch (e) {
737	      if (isMailcowUnreachable(e)) {
738	        mailcowUnreachable = true;
739	        console.warn(`[mailcow] delete ${mailbox.address}: unreachable, removing local record anyway:`, e);
740	      } else {
741	        console.error(`[mailcow] delete ${mailbox.address} REFUSED:`, e);
742	        return {
743	          error:
744	            "The mail server wouldn't remove this mailbox, so we've left it in place rather than lose your mail. Please try again in a moment, or contact support if it keeps happening.",
745	        };
746	      }
747	    }
748	  }
749	
750	  await db.mailbox.delete({ where: { id: mailbox.id } });
751	
752	  await db.auditLog.create({
753	    data: {
754	      userId: user.id,
755	      action: "mailbox.remove",
756	      detail: mailcowUnreachable ? `${mailbox.address} (mailcow unreachable — server-side delete not confirmed)` : mailbox.address,
757	    },
758	  });
759	  revalidatePath("/dashboard/email");
760	  return mailcowUnreachable
761	    ? {
762	        ok: true,
763	        warning:
764	          "Removed from your account. The mail server was unreachable, so the mailbox itself may still exist — it will be cleared when mail service is back, or contact support if messages keep arriving.",
765	      }
766	    : { ok: true };
767	}
