782	export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
783	  const admin = await requireAdmin();
784	  const serverId = String(formData.get("serverId") ?? "");
785	  const days = Number(formData.get("days"));
786	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
787	    return { error: "Days must be between -365 and 365." };
788	  }
789	  const server = await db.server.findUnique({ where: { id: serverId } });
790	  if (!server) return { error: "Server not found." };
791	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
792	
793	  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
794	  // The whole proration model rests on "every month between now and `expiresAt` is
795	  // a month the customer has actually bought" (see lib/proration.ts
796	  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
797	  // no call limit and no payment — so before the persisted rate existed, an admin
798	  // goodwill gift of 12 months was directly convertible to cash: downgrade the
799	  // gifted server and the prorated credit paid out real wallet money for months
800	  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
801	  // but a support agent clicking "extend" was minting refundable balance.
802	  //
803	  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
804	  // into the rate the existing months are on. That is the honest reading of a gift
805	  // — those months cost the customer nothing, so nothing may prorate out of them —
806	  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
807	  // remaining window completely unchanged, so a customer who paid for 12 months and
808	  // was gifted a 13th still gets back precisely what those 12 paid months are worth
809	  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
810	  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
811	  // toward 100, so no number of calls can raise the payout.
812	  //
813	  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
814	  // to blend in: the customer keeps the rate they bought at over a shorter window,
815	  // which strictly reduces any future credit. Blending negative months would push
816	  // the rate the other way and over-credit what is left.
817	  const gifted = days > 0;
818	  const termPromoPercent = gifted
819	    ? prorateBlendPercent({
820	        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
821	        currentMonths: remainingMonths(server.expiresAt, Date.now()),
822	        addedPercent: 100, // gifted: no cash changed hands for these months
823	        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
824	      })
825	    : resolveTermPromoPercent(server.termPromoPercent);
826	
827	  await db.server.update({
828	    where: { id: serverId },
829	    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
830	  });
831	  await audit(
832	    admin.id,
833	    "admin.extend_server",
834	    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
835	  );
836	  revalidatePath("/admin/subscriptions");
837	  return {};
838	}
